import{z as l,x as i,o as e,c as p,q as s,j as r,D as E,d as B,s as n,S as o,b as A}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"只读事务与快照","description":"","frontmatter":{"title":"只读事务与快照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/read-only-snapshot.md","filePath":"cs/read-only-snapshot.md","lastUpdated":1791413859000}'),d={name:"cs/read-only-snapshot.md"};function C(c,a,D,h,m,S){const t=i("Mermaid");return e(),p("div",null,[a[2]||(a[2]=s('<h1 id="只读事务与快照" tabindex="-1">只读事务与快照 <a class="header-anchor" href="#只读事务与快照" aria-label="Permalink to &quot;只读事务与快照&quot;">​</a></h1><div class="epigraph"><p>只读事务不安装写集，快照可在开始时钉死；读不阻塞写，但钉住的水位仍可能挡住 GC，除非快照被送到副本。</p><footer>—— 据 Fekete 等 SI；Postgres REPEATABLE READ；异步备库只读</footer></div><p><a href="/cs/mvcc-gc">上一课</a>把膨胀归到最小快照。本课专讲只读：主干隔离级别有只读优化。缺口是<strong>声明只读</strong>带来的协议变体：无写锁、无 OCC 验证写集、可在备库执行、可与 SSI 豁免交互。Calvin 下一课连写也确定性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读写事务的快照若在第一句才钉，可与 SI 异常相关；有的引擎事务开始即钉。只读：开始钉即可。缺口是一致性：只读要不要看见「自己开始后已提交的写」——不可重复读 vs 语句快照 vs 事务快照。分析查询要事务快照才可重复。</p><p>备库只读：物理复制延迟，读的是过去快照，GC 在主库若无 feedback 可不被备库查询钉住（备库自己 vacuum）。冲突：主库 replay 与备库查询锁行，hot standby 冲突。</p><p><span class="marginnote">直觉类比：钉快照像拍照定格——快门按下的瞬间画面固定，之后房间里的人怎么走动都与你这张照片无关。代价是只要这张照片还被拿着，房间里「没人站着挡镜头」的清理（GC）就不能进行；照相机越多、拿得越久，房间越挤。</span></p><p><span class="marginnote">只读优化不能改成脏读。读己之写在单机只读事务无写。分布式读己之写后课复制延迟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>BEGIN READ ONLY</code>：锁管理器不发 IX，优化器可选延迟物化与无间隙锁（在 SI 下）。导出快照 id 给其他连接（快照导入）做多会话一致读，水位仍钉。</p><p><span class="marginnote">数字实例：报表在备库读「订单总数」，主库每秒成交 2000 单、复制延迟 30 秒——你读到的数比主库真实值少约 6 万单。陈旧不是 bug 而是合同条款：要么把「允许落后 30 秒」写进 SLA，要么改用主库快照并接受它钉住 GC 水位的膨胀代价。</span></p><p>HTAP：分析只读走列存副本，OLTP 走行存，快照由复制 LSN 对齐——后课 HTAP。</p>',12)),(e(),r(o,null,{default:E(()=>[n(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RO%5B%22%E5%8F%AA%E8%AF%BB%E5%BC%80%E5%A7%8B%22%5D%20--%3E%20PIN%5B%22%E9%92%89%E5%BF%AB%E7%85%A7%22%5D%0A%20%20PIN%20--%3E%20READ%5B%22%E6%97%A0%E5%86%99%E9%94%81%E6%89%AB%E6%8F%8F%22%5D%0A%20%20PIN%20--%3E%20GC%5B%22%E4%BB%8D%E5%8F%AF%E8%83%BD%E9%92%89%20xmin%22%5D%0A%20%20REPL%5B%22%E5%A4%87%E5%BA%93%E5%8F%AA%E8%AF%BB%22%5D%20--%3E%20LAG%5B%22%E9%99%88%E6%97%A7%E4%BD%86%E5%B0%91%E6%8C%A1%E4%B8%BB%E5%BA%93%20GC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"计划：只读可串行在 SSI 下少 abort。并行工人共享同一快照号，否则各工人看见不同提交。exchange 课已要求。",-1)),(e(),r(o,null,{default:E(()=>[n(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%88%86%E6%9E%90%E6%9F%A5%E8%AF%A2%E5%B9%B6%E8%A1%8C%E6%8B%86%E6%88%90%E5%A4%9A%E4%B8%AA%E5%B7%A5%E4%BA%BA%22%5D%20--%3E%20S%7B%22%E5%90%84%E5%B7%A5%E4%BA%BA%E5%8F%96%E5%BF%AB%E7%85%A7%E7%9A%84%E6%96%B9%E5%BC%8F%EF%BC%9F%22%7D%0A%20%20S%20--%3E%7C%22%E5%90%84%E8%87%AA%E5%8F%96%E6%96%B0%E5%BF%AB%E7%85%A7%22%7C%20D%5B%22%E4%B8%8D%E5%90%8C%E5%B7%A5%E4%BA%BA%E7%9C%8B%E8%A7%81%E4%B8%8D%E5%90%8C%E6%97%B6%E7%82%B9%E7%9A%84%E6%8F%90%E4%BA%A4%22%5D%0A%20%20S%20--%3E%7C%22%E5%85%B1%E4%BA%AB%E5%90%8C%E4%B8%80%E5%BF%AB%E7%85%A7%E5%8F%B7%22%7C%20O%5B%22%E5%85%A8%E4%BD%93%E5%B7%A5%E4%BA%BA%E7%9C%8B%E5%88%B0%E5%90%8C%E4%B8%80%E6%97%B6%E7%82%B9%E6%95%B0%E6%8D%AE%22%5D%0A%20%20O%20--%3E%20E%5B%22%E6%B1%87%E5%90%88%E5%90%8E%E7%BB%93%E6%9E%9C%E5%8F%AF%E5%A4%8D%E7%8E%B0%22%5D%0A%20%20D%20--%3E%20F%5B%22%E5%90%8C%E4%B8%80%E8%81%9A%E5%90%88%E4%B8%A4%E6%AC%A1%E8%B7%91%E6%95%B0%E5%AF%B9%E4%B8%8D%E4%B8%8A%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">常见误区：初学者容易把「只读」当成一种隔离级别。它其实只是事务的一个属性标签，要和 READ COMMITTED、REPEATABLE READ、SSI 正交组合——同一个只读事务在不同隔离级别下看见的东西完全不同。声明只读换的是锁与验证的省略，不是隔离语义的放松。</span></p><p>与预编译：只读短查询仍走计划缓存；快照号每次新。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Calvin 定序。也不把只读当最终一致 OK 的借口——合同要写陈旧预算。RTO 是恢复课。</p><p>后课默认：分析用事务快照只读；怕膨胀则走副本。Calvin 确定性：先全局定序再无锁执行，读写都适用。</p><p>只读不是隔离级别，是事务属性；与 RR/SSI 正交组合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>只读钉快照、少锁；仍可能钉 GC 水位。</li><li>备库只读用延迟换主库膨胀。</li><li>Calvin 确定性下一课：定序代替冲突检测。</li><li>出处：SI 文献；Postgres 只读/备库；Gray。</li></ul>',8))])}const _=l(d,[["render",C]]);export{F as __pageData,_ as default};
